/* IlmuAlam Quran Engine (Enterprise) © 2026 ilmualam.com */
(function () {
  "use strict";

  // ========= Anti-tiru (domain lock) =========
  const ALLOW = ["ilmualam.com", "www.ilmualam.com", "ilmualam.blogspot.com", "blogger.com", "blogspot.com", "draft.blogger.com"];
  const host = (location.hostname || "").toLowerCase();
  const okHost = ALLOW.some(d => host === d || host.endsWith("." + d));
  if (!okHost) return;

  function boot() { document.querySelectorAll(".ilmq[data-surah]").forEach(init); }

  function init(root) {
    const surah = parseInt(root.getAttribute("data-surah"), 10);
    if (!surah || surah < 1 || surah > 114) return;

    const $ = (q) => root.querySelector(q);
    
    let versesEl = $('[data-bind="verses"]');
    let audio = $('[data-bind="audio"]');
    let playBtn = $('[data-action="playpause"]');
    let barWrap = $('[data-action="seek"]');
    let barFill = barWrap ? barWrap.querySelector("i") : null;
    let timeLabel = $('[data-bind="time"]');
    let qariSel = $('[data-bind="qari"]');
    let toastEl = $('[data-bind="toast"]');
    
    let verses = [];
    let idx = 0;
    let ready = false;

    // Toast Function
    const toast = (m) => {
      if(!toastEl) return;
      toastEl.textContent = m;
      toastEl.classList.add("on");
      clearTimeout(toastEl._t);
      toastEl._t = setTimeout(() => toastEl.classList.remove("on"), 1400);
    };

    // Format Time Function
    const formatTime = (s) => {
      if (!isFinite(s) || s < 0) return "0:00";
      const m = Math.floor(s / 60), sec = Math.floor(s % 60);
      return `${m}:${String(sec).padStart(2, "0")}`;
    };

    // UI Updates
    const setPlayUI = (playing) => {
      if (playBtn) {
        playBtn.setAttribute("aria-pressed", playing ? "true" : "false");
        playBtn.innerHTML = playing ? "⏸" : "▶️";
      }
    };

    const markPlaying = (index) => {
      if(!versesEl) return;
      versesEl.querySelectorAll(".v.playing").forEach(n => n.classList.remove("playing"));
      const card = versesEl.querySelector(`.v[data-i="${index}"]`);
      if (card) {
        card.classList.add("playing");
        card.scrollIntoView({ behavior: "smooth", block: "center" });
      }
    };

    async function loadAyah(index, autoplay) {
      idx = Math.max(0, Math.min(verses.length - 1, index));
      markPlaying(idx);

      if(audio) {
        const qari = qariSel ? qariSel.value : "Alafasy_128kbps";
        audio.src = `https://everyayah.com/data/${qari}/${String(surah).padStart(3,"0")}${String(idx + 1).padStart(3,"0")}.mp3`;
        audio.load();

        if (autoplay) {
          try { await audio.play(); setPlayUI(true); } 
          catch { setPlayUI(false); }
        } else {
          setPlayUI(false);
        }
      }
    }

    function renderVerses() {
      if(!versesEl) return;
      const frag = document.createDocumentFragment();
      verses.forEach((v, i) => {
        const card = document.createElement("article");
        card.className = "v";
        card.dataset.i = String(i);
        card.innerHTML = `
          <div class="top">
            <div class="no">${surah}:${i + 1}</div>
            <div class="va">
              <button class="vbtn" type="button" data-act="play">Play</button>
              <button class="vbtn" type="button" data-act="copy">Copy</button>
            </div>
          </div>
          <div class="arab">${v.arabic}</div>
          <p class="rumi"><strong>Rumi:</strong> ${v.rumi}</p>
          <p class="mal"><strong>Maksud:</strong> ${v.ms}</p>
        `;
        
        card.addEventListener("click", (e) => { 
            if(!e.target?.dataset?.act) loadAyah(i, true); 
        });
        
        card.querySelector('[data-act="play"]').addEventListener("click", (e) => { 
            e.stopPropagation(); 
            if (idx !== i) loadAyah(i, true); 
            else if (audio) { if (audio.paused) audio.play(); else audio.pause(); } 
        });

        card.querySelector('[data-act="copy"]').addEventListener("click", (e) => { 
            e.stopPropagation(); 
            navigator.clipboard.writeText(`${v.arabic}\n${v.ms}`); 
            toast("Disalin ✅"); 
        });

        frag.appendChild(card);
      });
      versesEl.innerHTML = ""; versesEl.appendChild(frag);
      markPlaying(idx);
    }

    async function loadSurah() {
      // API JSON 1-Request dari GitHub anda (cache: "no-store" memaksa pelayar ambil versi terbaru)
      const jsonUrl = `https://cdn.jsdelivr.net/gh/ilmualam/quran@main/data-surah/surah-${surah}.json`;
      
      let dataSurah;
      try {
          const response = await fetch(jsonUrl, { cache: "no-store" });
          if (!response.ok) throw new Error("Gagal HTTP");
          dataSurah = await response.json();
      } catch (err) {
          // Fallback Automatik Untuk Surah 106 jika JSON GitHub masih belum detect
          if(surah === 106) {
              dataSurah = [
                  { id: 1, arabic: "لِإِيلَٰفِ قُرَيْشٍ", rumi: "Li-ilaafi Quraisy", translation: "Kerana kebiasaan aman tenteram kaum Quraisy (penduduk Mekah)" },
                  { id: 2, arabic: "إِيلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ", rumi: "Iilaafihim rihlatas-syitaa'i was-sayf", translation: "(Iaitu) kebiasaan aman tenteram perjalanan mereka (menjalankan perniagaan) pada musim sejuk dan pada musim panas" },
                  { id: 3, arabic: "فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ", rumi: "Fal-ya'buduu Rabba haazal-bayt", translation: "Maka hendaklah mereka menyembah Tuhan yang menguasai rumah (Kaabah) ini" },
                  { id: 4, arabic: "ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍ", rumi: "Allazii at'amahum min juu'iw wa aamanahum min khawf", translation: "Tuhan yang memberi mereka penghidupan: menyelamatkan mereka dari kelaparan, dan mengamankan mereka dari ketakutan" }
              ];
          } else {
              if(versesEl) versesEl.innerHTML = `<div class="loading">❌ Ralat: Sila pastikan fail surah-${surah}.json telah di-upload ke folder /data-surah/ di GitHub.</div>`;
              return;
          }
      }

      verses = dataSurah.map((x) => ({
        arabic: x.arabic || "",
        ms: x.translation || x.ms || "",
        rumi: x.rumi || ""
      }));

      ready = true;
      renderVerses();
      await loadAyah(0, false);
    }

    // Event Listeners (Audio & Butang)
    if(playBtn) {
        playBtn.addEventListener("click", () => { 
            if(audio) { 
                if (!audio.src) loadAyah(idx, true); 
                else if (audio.paused) audio.play(); 
                else audio.pause(); 
            }
        });
    }

    if(qariSel) {
        qariSel.addEventListener("change", () => { 
            if (ready && audio) loadAyah(idx, !audio.paused); 
        });
    }
    
    if(audio) {
      audio.addEventListener("timeupdate", () => {
        if (!audio.duration) return;
        const pct = (audio.currentTime / audio.duration) * 100;
        if (barFill) barFill.style.width = pct.toFixed(2) + "%";
        if (timeLabel) timeLabel.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
      });
      audio.addEventListener("play", () => { setPlayUI(true); markPlaying(idx); });
      audio.addEventListener("pause", () => { setPlayUI(false); });
      audio.addEventListener("ended", async () => {
        setPlayUI(false);
        // Auto-next diaktifkan secara kekal
        if (idx + 1 < verses.length) await loadAyah(idx + 1, true);
      });
    }
    
    if(barWrap) {
        barWrap.addEventListener("click", (e) => {
            if (!audio || !audio.duration) return;
            const rect = barWrap.getBoundingClientRect();
            const x = Math.max(0, Math.min(rect.width, e.clientX - rect.left));
            audio.currentTime = (x / rect.width) * audio.duration;
        });
    }

    loadSurah();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot); 
  else boot();
})();
